def shell_pass(a,g):
    a=a[:]
    n=len(a)
    for start in range(g):
        for i in range(start+g,n,g):
            key=a[i]
            j=i-g
            while j>=start and a[j]>key:
                a[j+g]=a[j]
                j-=g
            a[j+g]=key
    return a

