from collections import deque

def feasible(target):
    dq = deque()
    nxt = 1
    ops = []
    for x in target:
        while nxt <= x:
            dq.append(nxt)
            ops.append(f'R_put({nxt})')
            nxt += 1
        if dq and dq[0] == x:
            dq.popleft()
            ops.append('L_pop')
        elif dq and dq[-1] == x:
            dq.pop()
            ops.append('R_pop')
        else:
            return None
    return ops

