def faults(seq, n, algo):
    frames = []
    age = {}
    cnt = 0
    for t, x in enumerate(seq):
        if x in frames:
            if algo == 'LRU':
                age[x] = t
            continue
        cnt += 1
        if len(frames) < n:
            frames.append(x)
        elif algo == 'FIFO':
            frames.pop(0)
            frames.append(x)
        else:
            victim = min(frames, key=lambda y: age[y])
            frames.remove(victim)
            frames.append(x)
        age[x] = t
    return cnt

